function objectivesTable(items){return `<div class="table-scroll"><table><thead><tr><th>Código</th><th>Objetivo estratégico</th><th>Perspectiva</th><th>Responsable</th><th>Prioridad</th><th>KPIs asociados</th><th>Cumpl. Promedio</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${items.map(o=>{const ks=state.kpis.filter(k=>k.objectiveId===o.id);const avg=weightedCompliance(ks.map(k=>({pct:achievement(k),weight:k.weight})));const stKey=avg===null?"neutral":avg>=90?"good":avg>=75?"warn":"bad";const stLabel=avg===null?"Sin datos":avg>=90?"✅ LOGRADO":avg>=75?"⚠️ EN RIESGO":"❌ CRÍTICO";return `<tr><td><span class="code">${escapeHtml(o.id)}</span></td><td><span class="table-title">${escapeHtml(o.name)}</span><span class="subcell" style="white-space:normal;max-width:360px">${escapeHtml(o.description)}</span></td><td>${escapeHtml(perspectiveLabel(o.perspective))}</td><td>${escapeHtml(o.owner)}</td><td><span class="tag">${escapeHtml(o.priority)}</span></td><td>${ks.length} KPIs</td><td><strong>${avg===null?"—":fmt(avg)+"%"}</strong></td><td><span class="status ${stKey}">${stLabel}</span></td><td><div class="table-actions"><button class="text-action" data-action="objective-detail" data-id="${o.id}">Ver KPIs</button>${canEdit()?`<button class="text-action" data-action="edit-objective" data-id="${o.id}">Editar</button><button class="text-action" data-action="delete-objective" data-id="${o.id}">Eliminar</button>`:""}</div></td></tr>`}).join("")||`<tr><td colspan="9"><div class="empty-state"><strong>No hay objetivos</strong>Cambia los filtros o registra un objetivo nuevo.</div></td></tr>`}</tbody></table></div><div class="table-bottom"><span>${items.length} objetivo(s) estratégico(s)</span><span>Semáforo: ✅ ≥90% | ⚠️ 75–89% | ❌ &lt;75%</span></div>`}
